import{_ as e,c as d,o,ae as r}from"./chunks/framework.CFeneB-q.js";const p=JSON.parse('{"title":"PC 端 · 入门","description":"","frontmatter":{},"headers":[],"relativePath":"pc/introduction.md","filePath":"pc/introduction.md","lastUpdated":1789438865000}'),a={name:"pc/introduction.md"};function n(c,t,i,s,l,h){return o(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="pc-端-·-入门" tabindex="-1">PC 端 · 入门 <a class="header-anchor" href="#pc-端-·-入门" aria-label="Permalink to &quot;PC 端 · 入门&quot;">​</a></h1><h2 id="平台定位" tabindex="-1">平台定位 <a class="header-anchor" href="#平台定位" aria-label="Permalink to &quot;平台定位&quot;">​</a></h2><p>E9 交付平台 / Keystone 2.0 是<strong>一套代码、多客户交付</strong>的工地信息化管理端：覆盖人员、质量、安全、机械、综合管理、材料成本、进度协同、环境管理等业务域，配套数据大屏（screen）子系统与系统管理功能。前端按客户以「标品 + 客户副本」方式交付，编译期按客户裁剪业务视图。</p><h2 id="多客户交付模式" tabindex="-1">多客户交付模式 <a class="header-anchor" href="#多客户交付模式" aria-label="Permalink to &quot;多客户交付模式&quot;">​</a></h2><p>两个机制叠加：</p><ol><li><strong>编译期裁剪</strong>：<code>pnpm start</code> 交互选择参与编译的业务视图，写入 <code>.env.&lt;mode&gt;</code> 的 <code>VITE_BUILD_VIEWS</code>（别名如 <code>fc,pzgc,st,cl</code>）；未选中的业务目录不参与编译。别名映射唯一配置源：<code>src/config/business.config.js</code>（fanchang=fc、pzgc、shate=st、changliu=cl、test=ts；keystone 为默认业务常驻）。</li><li><strong>每客户一个仓库副本</strong>：e9tech 工作区下 20+ 个 <code>*-deliver-ui / *-delivery-ui</code> 仓库，按客户定制后各自维护（详见族谱表）。</li></ol><h2 id="项目族谱" tabindex="-1">项目族谱 <a class="header-anchor" href="#项目族谱" aria-label="Permalink to &quot;项目族谱&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>技术栈</th><th>定位</th><th>状态</th></tr></thead><tbody><tr><td><code>e9tech/keystone-deliver-ui</code></td><td>Vue 3.3 + Vite 4 + Pinia + i18next + Arco</td><td><strong>标品</strong>（多客户机制的载体，本指南快速开始蓝本），客户副本从它派生</td><td>主线维护</td></tr><tr><td><code>e9tech/e9-delivery-ui</code></td><td>Vue 3.3 + Vite 4 + Pinia + vue-i18n + Arco</td><td>新基座（无多业务裁剪机制，views 为 backstage 单块结构）</td><td>维护中</td></tr><tr><td><code>e9tech/</code> 下其他 20+ 副本（changliu / demo / fanchang / g108 / nggs / qhgs / runcheng / sa / sate / snyh / st / wlksl / wzzn / zj / zjxy 等）</td><td>同标品</td><td>按客户定制的交付副本，各自维护</td><td>各自维护</td></tr><tr><td><code>admin-app/beam-web</code></td><td>Vue 2.6 + RuoYi + Element UI</td><td>工程施工信息化（梁场 / 拌合站 / 大屏）</td><td>存量</td></tr><tr><td><code>admin-app/e9-epim</code></td><td>Vue 2.6 + Element UI + BPMN</td><td>平台运营端（租户 / 审批 / 菜单）</td><td>存量</td></tr><tr><td><code>admin-app/e9-inspection-web</code></td><td>Vue 3.4 + Vite 5 + Element Plus</td><td>巡检独立小系统</td><td>存量</td></tr><tr><td><code>admin-app/e9ech</code></td><td>—</td><td>e9tech 的残缺拷贝</td><td><strong>废弃，勿参考</strong></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">副本现状提示</p><p>工作区存在 <code>keystone-deliver-ui - 副本</code>、<code>keystone-deliver-ui - 副本 - 副本</code> 等手工复制目录——<strong>勿作为开发蓝本</strong>，一律以 <code>keystone-deliver-ui</code> 标品仓库为准。副本派生记录的规范化已列入遗留项（缺口分析 §3.2）。</p></div><h2 id="术语表" tabindex="-1">术语表 <a class="header-anchor" href="#术语表" aria-label="Permalink to &quot;术语表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>含义</th></tr></thead><tbody><tr><td>交付端</td><td>给客户交付的 PC 管理端（本指南 PC 篇的主体）</td></tr><tr><td>运营端</td><td>e9-epim，平台侧运营管理系统（租户、审批、菜单配置）</td></tr><tr><td>大屏（screen）</td><td><code>views/screen/</code> 数据大屏子系统，自带路由 / store / hooks / 组件库的独立分层</td></tr><tr><td>SSO</td><td>单点登录平台（e9-sso-ui），各端统一跳转登录</td></tr><tr><td>租户（tenantId）</td><td>多客户隔离的单位，请求头携带</td></tr><tr><td>按钮 / 按钮权限</td><td>页面操作级权限，<code>v-permission</code> 指令 + <code>definePermission</code> 权限码（见规范篇）</td></tr><tr><td>i18n 词条分层</td><td>i18next 按预加载域（basic_components / common / screen）+ 路由级懒加载分层（见参考文档）</td></tr><tr><td><code>VITE_BUILD_VIEWS</code></td><td>控制参与编译业务视图的环境变量，<code>pnpm start</code> 写入</td></tr><tr><td><code>switch:api</code></td><td>切换请求指向哪个客户后端的脚本</td></tr></tbody></table><h2 id="读者指引" tabindex="-1">读者指引 <a class="header-anchor" href="#读者指引" aria-label="Permalink to &quot;读者指引&quot;">​</a></h2><ul><li><strong>新人</strong>：按本页入门 → <a href="./technology-stack.html">技术栈</a> → <a href="./getting-started.html">快速开始</a> 顺序，半天内本地跑起标品；再按 <a href="./project-structure.html">项目结构</a> → <a href="./function-development.html">功能开发</a> 独立提交第一个页面；</li><li><strong>只做 PC 交付</strong>：入门 → 快速开始 → 功能开发 → 规范（提交 / 代码风格 / 按钮权限 / i18n）；</li><li><strong>排查问题</strong>：参考文档六篇（请求封装、SSO 链路、环境变量、构建部署、按钮权限架构、i18n 架构）；</li><li><strong>移动端 / 桌面端同事</strong>：读对应端入门页的「多客户机制对照」，PC 的编译期裁剪与移动端的运行时下发是两套思路。</li></ul>',13)])])}const m=e(a,[["render",n]]);export{p as __pageData,m as default};
